extern void be_load_lvgl_classes(bvm *vm);

// Compact LVGL class methods tables, generated by `tools/convert.py` in `generate/be_lv_c_mapping.h`
// A method is 8 bytes: function, offset of its name (without verb prefix) in `lv_method_names`,
// verb code (3 high bits, index in `lv_method_verbs`) and signature index (13 low bits, in `lv_method_sigs`)
#define LV_METHOD_SIG_BITS    13      // must match METHOD_SIG_BITS in tools/convert.py
#define LV_METHOD_SIG_MASK    ((1 << LV_METHOD_SIG_BITS) - 1)
#define LV_MSIG(verb, sig)    (((verb) << LV_METHOD_SIG_BITS) | (sig))

typedef struct lv_ntv_method_t {
  const void * func;
  uint16_t name;                          // offset in `lv_method_names`
  uint16_t sig;                           // LV_MSIG(verb, signature index)
} lv_ntv_method_t;

typedef struct lv_ntv_sig_t {
  const char * return_type;
  const char * arg_type;
} lv_ntv_sig_t;

typedef struct lv_ntv_class_def_t {
  const char * name;                      // must be first for binary search
  const struct bclass * cl;
  const lv_ntv_method_t * methods;        // sorted by (verb, name)
  size_t size;
} lv_ntv_class_def_t;

// Generic style accessors: `obj.set_style_<p>(v, sel)`, `obj.get_style_<p>(part)` and `style.set_<p>(v)`
// are resolved at runtime from `lv_style_props[]` (generated in `generate/be_lv_c_mapping.h`)
// and call `lv_obj_set_local_style_prop()`, `lv_obj_get_style_prop()` and `lv_style_set_prop()`
// C value kinds, must match STYLE_KINDS in tools/convert.py
#define LV_SKIND_NUM      0       // int32_t or enum
#define LV_SKIND_U8       1       // uint8_t, ex: lv_opa_t
#define LV_SKIND_U16      2       // uint16_t
#define LV_SKIND_BOOL     3
#define LV_SKIND_COLOR    4       // lv_color_t
#define LV_SKIND_PTR      5       // pointer
// accessor flags, must match SPROP_* in tools/convert.py
#define LV_SPROP_OBJ_SET    0x01
#define LV_SPROP_OBJ_GET    0x02
#define LV_SPROP_STYLE_SET  0x04
#define LV_SPROP_INFO(type, flags)    ((type) | ((flags) << 5))   // type index is 5 bits

typedef struct lv_style_ntv_type_t {
  const char * value_arg;                 // Berry type of the value argument, ex: "(lv.color)"
  const char * return_type;               // Berry return type of the getter, ex: "lv.color"
  uint8_t kind;                           // LV_SKIND_*
} lv_style_ntv_type_t;

typedef struct lv_style_ntv_prop_t {
  uint16_t name;                          // offset in `lv_method_names`, name without verb, ex: "bg_color"
  uint8_t prop;                           // lv_style_prop_t
  uint8_t info;                           // LV_SPROP_INFO(type index, LV_SPROP_* flags)
} lv_style_ntv_prop_t;

// `lv` module constants grouped by prefix to save flash.
// Ex: `lv.STYLE_BG_COLOR` is stored as "BG_COLOR" in the "STYLE" group
// Generated by `tools/convert.py` in `generate/be_lvgl_module.c`
typedef struct lv_const_group_t {
  const char * prefix;                    // prefix without trailing `_`, must be first for binary search
  const struct be_const_member_t * members; // sorted table, names without prefix
  size_t size;                            // number of members
} lv_const_group_t;

extern void lv_image_set_tasmota_logo(lv_obj_t * img);
